                $operator = strtoupper((string) ($term['operator'] ?? ''));
                $left = $term['left'] ?? null;
                $value = is_array($left) && isset($left['expression'])
                    ? self::expressionValueNext161((string) $left['expression'], $row)
                    : $row[(string) ($left['column'] ?? '')] ?? null;
