                    foreach (is_array($term['values'] ?? null) ? $term['values'] : [] as $expected) {
                        if (self::compareNext161($value, self::literalNext161($expected), $collation) === 0) {
                            $matched = true;
                            break;
                        }
                    }
                    if (!$matched) {
                        return false;
                    }
                }
                if ($operator === 'IS NOT NULL' && $value === null) {
                    return false;
                }
            }

            return true;
