                $left = $term['left'] ?? null;
                if (!is_array($left) || !isset($left['column'])) {
                    continue;
                }
                $column = (string) $left['column'];
                $value = $row[$column] ?? null;
                if ($operator === '=' && $value !== ($term['right'] ?? null)) {
                    return false;
                }
                if ($operator === 'IS NOT NULL' && $value === null) {
                    return false;
                }
            }

            return true;
        }

