                    $comparison = self::compareNext171($value, self::literalNext171($term['right'] ?? null), $collation);
                    if (($operator === '>' && $comparison <= 0)
                        || ($operator === '>=' && $comparison < 0)
                        || ($operator === '<' && $comparison >= 0)
                        || ($operator === '<=' && $comparison > 0)) {
                        return false;
                    }
                }
            }

            return true;
        }

        /**
