            if ($operator === $partialOperator && self::literalNext171($term['right'] ?? null) === self::literalNext171($partial['right'] ?? null)) {
                return true;
            }
            if (in_array($operator, ['=', '>', '>=', '<', '<='], true) && in_array($partialOperator, ['>', '>=', '<', '<='], true)) {
