                    '>=' => in_array($operator, ['=', '>', '>='], true) && $comparison >= 0,
                    '<' => in_array($operator, ['=', '<', '<='], true) && $comparison < 0,
                    '<=' => in_array($operator, ['=', '<', '<='], true) && $comparison <= 0,
                    default => false,
