                'tableLookupDeferred' => true,
                'residualPredicateRequired' => true,
                'detail' => ($stale ? 'REPREPARE' : 'REUSE') . ' STAT4 PARTIAL EXPRESSION CURRENT SOURCE ' . (string) ($selected['indexName'] ?? 'NO INDEX'),
                'dependencies' => [
