                $sampleEstimate = array_sum(array_map(static fn (array $sample): int => $sample['nEq'], $matchedSamples));
                $estimatedRows = max(1, min(count($matchedRows), $sampleEstimate > 0 ? $sampleEstimate : count($matchedRows)));
