                foreach (self::listTermsNext172($partial) as $arm) {
                    if (self::predicateContainsNext172($predicate, $arm)) {
                        return true;
                    }
                }
            }

            return false;
        }

        private static function predicateContainsNext172(array $predicate, array $needle): bool
