                    $lower = self::stringOrNullNext230($term['lower'] ?? null);
                    $upper = self::stringOrNullNext230($term['upper'] ?? null);
                    if (($lower !== null && $stringValue < $lower) || ($upper !== null && $stringValue > $upper)) {
