            foreach ($queryTerms as $term) {
                $left = $term['left'] ?? null;
                if (($term['operator'] ?? null) === '=' && is_array($left) && ($left['column'] ?? null) === $predicate->columnName && ($term['right'] ?? null) === $predicate->value) {
