        if ($predicate->operator === SQLiteIndexPredicate::IS_NOT_NULL) {
            foreach ($queryTerms as $term) {
                $left = $term['left'] ?? null;
                if (($term['operator'] ?? null) === 'IS NOT NULL' && is_array($left) && ($left['column'] ?? null) === $predicate->columnName) {
                    return true;
                }
            }
        }

        return false;
    }

