            $matched[] = [
                'key' => $key,
                'nEq' => (int) ($sample['nEq'] ?? 1),
                'nLt' => (int) ($sample['nLt'] ?? 0),
                'nDLt' => (int) ($sample['nDLt'] ?? 0),
                'rowid' => (int) ($sample['rowid'] ?? 0),
