        foreach ($plan['rows'] as $row) {
            $payload = [];
            foreach ($neededColumns as $column) {
                if (!in_array($column, $plan['missingCoveringColumns'], true)) {
                    $payload[$column] = $row[$column] ?? null;
                }
            }
            $rows[] = ['rowid' => (int) ($row['rowid'] ?? 0), 'payload' => $payload];
        }

        return $rows;
    }

